// Split the model output back into an aligned bullets array, and guard the output.
const out = $input.first().json;
let raw = (out.choices?.[0]?.message?.content ?? out.message?.content ?? out.roman_urdu ?? '').trim();
raw = raw.replace(/^```[a-z]*\n?/i, '').replace(/```$/, '').replace(/^(roman urdu|translation)\s*[:-]\s*/i, '').trim();

const lines = raw.split('\n');
const title_ur = lines[0] || '';
const bullets_ur = lines.slice(1).map(l => l.replace(/^\s*[-*\u2022]\s*/, '').trim()).filter(Boolean);

// Safety: never let Urdu/Arabic script reach the card renderer
const urduScript = /[\u0600-\u06FF\u0750-\u077F\uFB50-\uFDFF\uFE70-\uFEFF\u0900-\u097F]/;
const clean = s => s.replace(/[\u0600-\u06FF\u0750-\u077F\uFB50-\uFDFF\uFE70-\uFEFF\u0900-\u097F]/g, '');

return [{ json: {
  ...out,
  title_ur: clean(title_ur),
  bullets_ur: bullets_ur.map(clean),
  card_text_ur: clean([title_ur, ...bullets_ur.map(b => '- ' + b)].join('\n')),
  translation_ok: !urduScript.test(raw) && bullets_ur.length >= 3 && bullets_ur.length <= 5
}}];
